-- ============================================================
-- Quiz coverage top-up for devops/istio (intermediate + advanced)
-- -- 10 questions, 5 per section, to bring Istio to full 20-question/
-- 4-section parity with sibling DevOps technologies (jenkins, terraform).
-- Istio only had overview+fundamentals coverage (10 questions) because
-- intermediate.md/advanced.md/certification.md didn't exist on disk
-- until this session's brand-logo-rollout-adjacent Istio content batch
-- (2026-09-03, see docs/audit/15-backlog-prioritization.md). Grounded
-- directly in that new intermediate.md/advanced.md content. Zero
-- within-file or cross-file duplicates, verified against the live DB
-- before applying (checked here, not just written and assumed clean).
-- ============================================================

INSERT INTO quiz_questions (academy_slug, technology_slug, section_slug, question, options, correct_index, explanation, difficulty) VALUES
('devops', 'istio', 'intermediate', 'In Istio''s ambient mode, what is ztunnel responsible for?', '["Full L7 traffic management (retries, fault injection) for every pod on the mesh", "A shared, per-node proxy handling L4 (mTLS, basic routing) for every pod on that node, with zero per-pod sidecar overhead", "Replacing istiod as the control plane entirely", "Only collecting Prometheus metrics, with no routing responsibility"]', 1, 'ztunnel is a shared per-node proxy handling L4 concerns (mTLS, basic routing) for every pod on that node -- ambient mode''s alternative to a sidecar-per-pod, with L7 features handled separately by an optional waypoint proxy only where needed.', 'intermediate'),
('devops', 'istio', 'intermediate', 'Why does ambient mode''s savings specifically come from services that don''t use L7 traffic-management features?', '["Because ztunnel actually runs slower than a sidecar for L7 traffic", "Because ztunnel only handles L4 for free; any service that needs L7 features (fine-grained routing, fault injection) still needs a waypoint proxy, which is the sidecar-equivalent cost for that specific service", "Because L7 features are being deprecated in future Istio releases", "Because ambient mode disables mTLS for L7 workloads"]', 1, 'Ambient mode''s cost savings are real but conditional: services needing only L4 (mTLS, basic routing) get it free via the shared per-node ztunnel, but a service that needs L7 features still requires a waypoint proxy -- so the savings don''t apply mesh-wide if most services rely on L7 traffic management.', 'advanced'),
('devops', 'istio', 'intermediate', 'In a multi-cluster Istio mesh using the primary-remote topology, what must be shared across both clusters for cross-cluster mTLS to work at all?', '["Nothing -- Istio automatically negotiates trust between any two clusters", "A shared root CA -- both clusters'' workload certificates must chain to the same root, or cross-cluster mTLS fails identity verification", "The same Kubernetes version on both clusters", "A shared etcd instance between the two clusters'' control planes"]', 1, 'Cross-cluster mTLS requires a shared root CA so both clusters'' workload certificates chain to the same trust root -- without it, identity verification between clusters fails even if network connectivity itself works.', 'advanced'),
('devops', 'istio', 'intermediate', 'What does an east-west gateway specifically handle in a multi-cluster Istio setup, as distinct from the regular ingress gateway?', '["External traffic from outside the mesh entirely", "Cluster-to-cluster traffic specifically -- a dedicated gateway distinct from the regular north-south ingress gateway that handles external traffic", "Only traffic between namespaces within a single cluster", "TLS certificate rotation for the whole mesh"]', 1, 'An east-west gateway is a dedicated Istio ingress gateway configured specifically for cluster-to-cluster (east-west) traffic, distinct from the regular ingress gateway that handles external, north-south traffic into the mesh.', 'advanced'),
('devops', 'istio', 'intermediate', 'When should EnvoyFilter be reached for instead of VirtualService/DestinationRule, per Istio''s own recommendation?', '["As the first choice for any traffic-routing task, since it is more powerful", "Only when no higher-level Istio API covers the need -- EnvoyFilter patches Envoy''s own config structures directly and isn''t guaranteed API-stable across Istio/Envoy version upgrades the way VirtualService is", "Only for securing workloads with mTLS, never for traffic management", "Never -- EnvoyFilter has been fully deprecated in favor of Sidecar resources"]', 1, 'EnvoyFilter is Istio''s low-level escape hatch, recommended only when no higher-level API (VirtualService, DestinationRule, etc.) covers the need -- it patches Envoy config structures directly, which aren''t guaranteed to stay API-stable across version upgrades the way the higher-level APIs are.', 'intermediate'),
('devops', 'istio', 'advanced', 'What is the most common real root cause of inconsistent routing to a host with no application-log errors at all?', '["A network partition between the two clusters", "Two VirtualServices defining routing rules for the same host, often shipped independently by two teams or two Helm charts without either side realizing the other exists", "The DestinationRule''s circuit breaker firing on every request", "An expired mTLS certificate on the destination service"]', 1, 'This is called out as a specific, common production incident pattern: two VirtualServices claiming the same host merge/override in a way that''s easy to get wrong, and since the request is misrouted by Envoy before reaching the application, no application-level error is ever logged.', 'advanced'),
('devops', 'istio', 'advanced', 'Roughly how much added latency does a single service-to-service call typically incur purely from Istio''s sidecar proxying, per the advanced content?', '["No added latency -- sidecars are fully transparent", "Roughly 1-3ms, since the call passes through the caller''s outbound sidecar AND the callee''s inbound sidecar -- two proxy hops per call, not one", "50-100ms per hop", "Latency added only scales with cluster size, not per-call"]', 1, 'The advanced content states roughly 1-3ms of added latency per hop, since both the caller''s outbound sidecar and the callee''s inbound sidecar process the request -- two hops per service-to-service call, not one.', 'advanced'),
('devops', 'istio', 'advanced', 'What does Flagger automate on top of Istio that a manual canary rollout otherwise requires a human to do?', '["Installing Istio itself across a new cluster", "Gradually shifting VirtualService/DestinationRule traffic weight while gating each step on real success-rate/latency metrics, with automatic rollback on failure, instead of a human manually editing weights while watching dashboards", "Issuing and rotating mTLS certificates mesh-wide", "Generating the initial VirtualService and DestinationRule YAML from scratch"]', 1, 'Flagger automates exactly what a manual canary rollout does by hand -- progressively shifting the underlying VirtualService/DestinationRule traffic weights, gated on real metrics thresholds, with automatic rollback if a check fails -- rather than a human watching dashboards and editing weights manually.', 'advanced'),
('devops', 'istio', 'advanced', 'Why is a RequestAuthentication resource alone not enough to make a JWT mandatory for a service?', '["RequestAuthentication cannot validate JWTs at all, only issue them", "RequestAuthentication only validates a JWT IF one is provided -- it does not reject requests that send no token at all, so a separate AuthorizationPolicy denying notRequestPrincipals is needed to actually require one", "JWTs are validated by Citadel, not RequestAuthentication, regardless of configuration", "RequestAuthentication requires a paid Istio add-on to enforce mandatory tokens"]', 1, 'RequestAuthentication validates a JWT if one is sent, but does not by itself require that one be present -- an unauthenticated request with no token is silently allowed through unless a separate AuthorizationPolicy explicitly denies requests matching notRequestPrincipals.', 'advanced'),
('devops', 'istio', 'advanced', 'What specifically does mTLS prove about a service-to-service call that a RequestAuthentication/JWT check does not, and vice versa?', '["They prove exactly the same thing -- one is redundant with the other", "mTLS proves which SERVICE made the call (workload identity); a JWT additionally proves which END USER the call is being made on behalf of -- mTLS alone cannot express user-level identity", "mTLS only works for external traffic; JWTs only work for internal traffic", "JWTs replace the need for mTLS entirely once configured"]', 1, 'mTLS establishes service-to-service (workload) identity -- proving which service is calling -- while a JWT via RequestAuthentication additionally proves which end user the call is made on behalf of, an orthogonal layer mTLS alone cannot express.', 'advanced');
